 import unittest
from candidate import sum_to_n

class TestSumToN(unittest.TestCase):
    def test_sum_to_n_positive_number(self):
        self.assertEqual(sum_to_n(30), 465)

    def test_sum_to_n_zero(self):
        self.assertEqual(sum_to_n(0), 0)

    def test_sum_to_n_negative_number(self.assertRaises(ValueError, sum_to_n, -1))

    def test_sum_to_n_boundary_condition_1(self):
        self.assertEqual(sum_to_n(1), 1)

    def test_sum_to_n_boundary_condition_n1(self):
        self.assertEqual(sum_to_n(2), 3)

    def test_sum_to_n_boundary_condition_n(self):
        self.assertEqual(sum_to_n(100), 5050)

    def test_sum_to_n_edge_case_zero(self):
        self.assertEqual(sum_to_n(0), 0)

    def test_sum_to_n_edge_case_one(self):
        self.assertEqual(sum_to_n(1), 1)

    def test_sum_to_n_edge_case_large_number(self):
        self.assertEqual(sum_to_n(10000), 500005000)

if __name__ == '__main__':
    unittest.main()
